/// <summary>
/// Showcase FactBox part that hosts <c>DocBulkFileUploadControl</c> in the Related information pane of
/// the Purchase order form. The control attaches files to the current purchase order header and runs
/// the compact upload-on-drop flow. This form is a demo host and is not part of the shipped product.
/// </summary>
[Form]
public class DocPurchOrderBulkUploadFactBox_DCBU extends FormRun
{
}

/// <summary>
/// Opens the standard Attachments page for the purchase order header this FactBox is bound to.
/// </summary>
private void openAllAttachments_DCBU()
{
    PurchTable hostPurchTable = this.getHostPurchTable_DCBU();

    // Without a resolved host the platform shows the empty "Attachments for Unlinked" grid.
    if (!hostPurchTable || !hostPurchTable.RecId)
    {
        DocGlobalHelper::handleWarning("@SYS94694"); // The record no longer exists.
        return;
    }

    DocuRef lookupDocuRef;
    lookupDocuRef.RefTableId   = DocuRef::GetRootTableID(tableNum(PurchTable));
    lookupDocuRef.RefRecId     = hostPurchTable.RecId;
    lookupDocuRef.RefCompanyId = hostPurchTable.DataAreaId;

    // DocuView.init() refuses to open when a view is already registered for the session.
    if (Docu::Instance() && Docu::Instance().docuView())
    {
        Docu::Instance().clearDocuView();
    }

    Args args = new Args();
    args.lookupRecord(lookupDocuRef);

    new MenuFunction(menuItemDisplayStr(DocuView), MenuItemType::Display).run(args);
}

/// <summary>
/// Returns the purchase order header record the FactBox is bound to, read from the cursor of the
/// PurchTable data source. Falls back to the record the host form passed to this part.
/// </summary>
/// <returns>The host purchase order header record, or an empty buffer if it cannot be resolved.</returns>
/// <remarks>
/// The auto-declared PurchTable buffer must not be used here: on the list page preview its RecId can
/// still be 0.
/// </remarks>
private PurchTable getHostPurchTable_DCBU()
{
    FormDataSource purchTableDs = this.dataSource(formDataSourceStr(DocPurchOrderBulkUploadFactBox_DCBU, PurchTable)) as FormDataSource;
    PurchTable     hostPurchTable = purchTableDs ? purchTableDs.cursor() : null;

    if (hostPurchTable && hostPurchTable.RecId)
    {
        return hostPurchTable;
    }

    // Fallback: the record the host form passed to this FactBox part.
    if (this.args() && this.args().record() && this.args().record().TableId == tableNum(PurchTable))
    {
        return this.args().record();
    }

    return hostPurchTable;
}

/// <summary>
/// Called when another purchase order becomes the current record. Tells the embedded upload
/// control whether that order still accepts new attachments.
/// </summary>
/// <returns>The status returned by the super() call.</returns>
/// <remarks>
/// The data source is display-only, so a data-source behavior would block every order. The
/// eligibility is resolved from the order's business state and installed as a fixed behavior.
/// </remarks>
public int active()
{
    int ret = super();

    PurchTable purchTableRecord = this.cursor();
    if (FactBoxBulkUploadControl_DCBU && purchTableRecord && purchTableRecord.RecId)
    {
        FactBoxBulkUploadControl_DCBU.setAccessBehavior(
            DocBulkFileUploadFixedAccessBehavior::construct(
                DocPurchOrderBulkUploadShowcase_DCBU::isPurchTableAttachEligible(purchTableRecord)));
    }

    return ret;
}

/// <summary>
/// Opens the standard Attachments grid for the host purchase order header.
/// </summary>
public void clicked()
{
    super();
    element.openAllAttachments_DCBU();
}
